        );
        let ordinary = crate::cleanup_plan::replay::validate_program(&program).unwrap_err();
        if crate::hir::lexical_exit::requires(function).unwrap() {
            assert_eq!(ordinary, selected, "lexical ordinary first six fields");
        } else {
