                plan.edges[0].condition = EdgeCondition::BooleanResult(
                    ExpressionId::from_owned("unknown.λ\0identity".to_owned()),
                    true,
                )
            }
            _ => unreachable!(),
        }
        same_owner(&program, "probe", false);
    }
}

